      {
        "dayDate": "October 13, 2024",
        "time": "12:45 - 14:00",
        "activity": "Closing Lunch",
        "duration": "75 Minutes"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_text",
        "description_text",
        "itinerary_table_card",
        "cta_text",
        "register_button"
      ]
    },
    "title_text": {
      "type": "Text",
      "props": {
        "text": "Annual Leadership Summit",
        "variant": "h1"
      },
      "children": []
    },
    "description_text": {
      "type": "Text",
      "props": {
        "text": "Join us for two days of insightful discussions, strategic workshops, and networking opportunities with industry leaders.",
        "variant": "body"
      },
      "children": []
    },
    "itinerary_table_card": {
      "type": "Card",
      "props": {},
      "children": [
        "itinerary_table_title",
        "itinerary_table"
      ]
    },
    "itinerary_table_title": {
      "type": "Text",
      "props": {
        "text": "Event Schedule",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "statePath": "/itinerary",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "activity",
        "highlightColumns": [
          "time",
          "duration"
        ],
        "columns": [
          {
            "key": "dayDate",
            "label": "Date"
          },
          {
            "key": "time",
            "label": "Time"
          },
          {
            "key": "activity",
            "label": "Activity"
          },
          {
            "key": "duration",
            "label": "Duration"
          }
        ]
      },
      "children": []
    },
    "cta_text": {
      "type": "Text",
      "props": {
        "text": "Don't miss out on this exclusive event!",
        "variant": "body"
      },
      "children": []
    },
    "register_button": {
      "type": "Button",
      "props": {
        "label": "Register Now"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/register"
          }
        }
      }
    }
  }
}
